const { registerConsentHandler } = require(path.join(root, 'dist-electron/main/consent.js'));
const { registerPasteHandler } = require(path.join(root, 'dist-electron/main/paste.js'));
const { startSession, stopSession } = require(path.join(root, 'dist-electron/main/session.js'));

const tmpData = await mkdtemp(path.join(os.tmpdir(), 'cp-s17-'));

app.whenReady().then(async () => {
  registerConsentHandler(page);
  registerPasteHandler();
  ipcMain.handle('cp:session:start', async (_event, payload) => {
    const meta = await startSession(tmpData, { epochMs: Date.now(), monoUs: Math.round(performance.now() * 1000) }, payload.timeControl);
    return { sessionId: meta.id };
  });
  ipcMain.handle('cp:session:stop', async () => {
