  const resignation = await readFile(path.join(root, 'tests/fixtures/pgn/resignation.pgn'), 'utf8');
  const aborted = await readFile(path.join(root, 'tests/fixtures/pgn/aborted.pgn'), 'utf8');
  const clockless = checkmate.replace(/\s*\{\[%clk [^\]]+\]\}/g, '');

  const results = await win.webContents.executeJavaScript(`
    (async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      const clickText = (text) => {
        const btn = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === text);
        if (!btn) throw new Error('Missing button: ' + text);
        btn.click();
      };
      const setTextarea = (index, value) => {
        const el = document.querySelectorAll('textarea')[index];
        if (!el) throw new Error('Missing textarea ' + index);
        const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const waitTag = async (expected) => {
        for (let i = 0; i < 40; i++) {
          const tag = document.querySelector('.state-tag')?.textContent?.trim();
          if (tag === expected) return tag;
          await wait(25);
        }
        return document.querySelector('.state-tag')?.textContent?.trim();
      };

      // Flow: allow camera -> start -> stop -> paste
      clickText('Allow the camera');
      await wait(100);
      clickText('Start sensing');
      await wait(100);
      clickText('Stop sensing');
      await wait(100);
      clickText('Paste PGNs');
      await wait(100);

      const emptyState = await waitTag('Empty');
      const continueDisabledOnEmpty = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === 'Continue to report')?.disabled;

      // Partial: 1 game in 3 slots
      setTextarea(0, ${JSON.stringify(resignation)});
      const partialState = await waitTag('Partial');

      // Out of order: put later game (checkmate 12:10) before earlier (resignation 12:06)
      setTextarea(0, ${JSON.stringify(checkmate)});
      setTextarea(1, ${JSON.stringify(resignation)});
      const oooState = await waitTag('Out of order');
      const oooDisabled = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === 'Continue to report')?.disabled;
      const oooBanner = document.querySelector('.banner-message')?.textContent?.trim();

      // Fix order with Move up on Game 2!
      const moveUp2 = document.querySelector('button[aria-label="Move game 2 up"]');
      moveUp2.click();
      const fixedPartialState = await waitTag('Partial');

      // Clockless state
      setTextarea(0, ${JSON.stringify(clockless)});
      setTextarea(1, '');
      const clocklessState = await waitTag('Clockless');
      const clocklessBanner = document.querySelector('.banner-message')?.textContent?.trim();

      // All valid: fill all 3 slots (undated checkmate, aborted, undated resignation)
      const u1 = ${JSON.stringify(resignation.replace(/\[(EndDate|EndTime|UTCDate|UTCTime)\s+"[^"]*"\]\r?\n/g, ''))};
      const u2 = ${JSON.stringify(aborted)};
      const u3 = ${JSON.stringify(checkmate.replace(/\[(EndDate|EndTime|UTCDate|UTCTime)\s+"[^"]*"\]\r?\n/g, ''))};
      setTextarea(0, u1);
      setTextarea(1, u2);
      setTextarea(2, u3);
      const validState = await waitTag('All valid');
      const validContinueEnabled = ![...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === 'Continue to report')?.disabled;
      const badBridge = await window.chesspulse.validatePgns('not-an-array').then(() => 'accepted', (e) => e.message);

      return {
