  console.log(JSON.stringify({ ...results, consoleErrors, ok }, null, 2));
  app.exit(ok ? 0 : 1);
}).catch(async (error) => {
  await rm(tmpData, { recursive: true, force: true });
  console.error(error);
  app.exit(1);
});
