      const confidence = document.querySelector('.timeline-confidence')?.textContent?.trim();
      const elevatedRuns = document.querySelectorAll('.pulse-elevated').length;
      const settledRuns = document.querySelectorAll('.pulse-settled').length;
      const cplTicks = document.querySelectorAll('.cpl-tick').length;
      const thinkDots = document.querySelectorAll('.think-dot').length;
      const endings = document.querySelectorAll('.ending-mark').length;
      const hatch = document.querySelectorAll('.elevated-zone rect').length;

      // Keyboard stepping test
      const frame = document.querySelector('.timeline-frame');
      frame.focus();
      await wait(50);
      const readout0 = document.querySelector('.timeline-readout')?.textContent?.trim();
      frame.dispatchEvent(new KeyboardEvent('keydown', { key: 'End', bubbles: true }));
      await wait(50);
      const readoutEnd = document.querySelector('.timeline-readout')?.textContent?.trim();

      // Now switch to inferred PGN (no EndTime) -> low_confidence banner
      clickText('Edit pasted PGNs');
      await wait(100);
      setTextarea(0, ${JSON.stringify(inferredPgn)});
      await wait(150);
      clickText('Continue to report');
      const lowConf = await waitSelector('.timeline-low_confidence');
      const lowConfBanner = document.querySelector('.timeline-banner')?.textContent?.trim();

      return {
        alignedRendered: Boolean(tl),
        confidence,
        elevatedRuns,
        settledRuns,
        cplTicks,
        thinkDots,
        endings,
        hatch,
        readout0,
        readoutEnd,
        lowConfRendered: Boolean(lowConf),
        lowConfBanner,
      };
    })()
  `, true);

  // Switch to low-coverage session and verify refusal + desaturated trace
  mode = 'low';
  const resRefusal = await win.webContents.executeJavaScript(`
    (async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      const clickText = (text) => {
        const btn = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === text);
        if (!btn) throw new Error('Missing button: ' + text);
        btn.click();
      };
      const setTextarea = (index, value) => {
        const el = document.querySelectorAll('textarea')[index];
        const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const waitSelector = async (sel) => {
        for (let i = 0; i < 80; i++) {
          const el = document.querySelector(sel);
          if (el) return el;
          await wait(50);
        }
        return null;
      };

      clickText('Back to session');
      await wait(100);
      clickText('Start sensing');
      await wait(100);
      clickText('Stop sensing');
      await wait(100);
      clickText('Paste PGNs');
      await wait(100);
      setTextarea(0, ${JSON.stringify(alignedPgn)});
      await wait(150);
      clickText('Continue to report');

      const tl = await waitSelector('.timeline-low_coverage');
      const refusalTitle = document.querySelector('.refusal-panel h2')?.textContent?.trim();
      const refusalMetric = document.querySelector('.refusal-metric')?.textContent?.trim();
      const desaturated = document.querySelectorAll('.pulse-desaturated').length;
      const elevatedOnRefusal = document.querySelectorAll('.pulse-elevated').length;
      const cplOnRefusal = document.querySelectorAll('.cpl-tick').length;

      return {
        refusalRendered: Boolean(tl),
        refusalTitle,
        refusalMetric,
        desaturated,
        elevatedOnRefusal,
        cplOnRefusal,
      };
    })()
  `, true);

  await rm(tmpData, { recursive: true, force: true });
  const ok =
    consoleErrors.length === 0 &&
    resAligned.alignedRendered &&
    resAligned.confidence === 'Aligned from EndTime (±1 s)' &&
    resAligned.elevatedRuns > 0 &&
    resAligned.settledRuns > 0 &&
    resAligned.cplTicks === 7 &&
    resAligned.thinkDots === 7 &&
    resAligned.endings === 1 &&
    resAligned.hatch === 1 &&
    resAligned.readout0?.includes('70 bpm') &&
    resAligned.readoutEnd?.includes('86 bpm') &&
    resAligned.readoutEnd?.includes('elevated') &&
    resAligned.lowConfRendered &&
    resAligned.lowConfBanner?.includes('No EndTime or UTC start') &&
    resRefusal.refusalRendered &&
    resRefusal.refusalTitle === 'No report for this session.' &&
    resRefusal.refusalMetric === 'Coverage was 40%; a review needs 70%.' &&
    resRefusal.desaturated > 0 &&
    resRefusal.elevatedOnRefusal === 0 &&
    resRefusal.cplOnRefusal === 0;

  console.log(JSON.stringify({ resAligned, resRefusal, consoleErrors, ok }, null, 2));
  app.exit(ok ? 0 : 1);
}).catch(async (error) => {
  await rm(tmpData, { recursive: true, force: true });
  console.error(error);
  app.exit(1);
});
