        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const waitSelector = async (sel) => {
        for (let i = 0; i < 80; i++) {
          const el = document.querySelector(sel);
          if (el) return el;
          await wait(50);
        }
        return null;
      };

      clickText('Back to session');
      await wait(100);
      clickText('Start sensing');
      await wait(100);
      clickText('Stop sensing');
      await wait(100);
      clickText('Paste PGNs');
      await wait(100);
