      const refusalTitle = document.querySelector('.refusal-panel h2')?.textContent?.trim();
      const refusalMetric = document.querySelector('.refusal-metric')?.textContent?.trim();
      const desaturated = document.querySelectorAll('.pulse-desaturated').length;
      const elevatedOnRefusal = document.querySelectorAll('.pulse-elevated').length;
      const cplOnRefusal = document.querySelectorAll('.cpl-tick').length;

      return {
        refusalRendered: Boolean(tl),
        refusalTitle,
        refusalMetric,
        desaturated,
        elevatedOnRefusal,
        cplOnRefusal,
      };
    })()
  `, true);

  await rm(tmpData, { recursive: true, force: true });
  const ok =
    consoleErrors.length === 0 &&
    resAligned.alignedRendered &&
    resAligned.confidence === 'Aligned from EndTime (±1 s)' &&
    resAligned.elevatedRuns === 1 &&
    resAligned.settledRuns === 1 &&
    resAligned.cplTicks + resAligned.cplUnscored === 7 &&
    resAligned.thinkDots === 7 &&
    resAligned.endings === 1 &&
    resAligned.hatch === 1 &&
    resAligned.readoutHome?.includes('70 bpm · settled') &&
    resAligned.readoutEnd?.includes('86 bpm · elevated') &&
    resAligned.lowConfRendered &&
    resAligned.lowConfBanner?.includes('No EndTime or UTC start') &&
    resRefusal.refusalRendered &&
    resRefusal.refusalTitle === 'No report for this session.' &&
    resRefusal.refusalMetric === 'Coverage was 40%; a review needs 70%.' &&
    resRefusal.desaturated === 1 &&
    resRefusal.elevatedOnRefusal === 0 &&
    resRefusal.cplOnRefusal === 0;

  console.log(JSON.stringify({ resAligned, resRefusal, consoleErrors, ok }, null, 2));
  app.exit(ok ? 0 : 1);
}).catch(async (error) => {
  await rm(tmpData, { recursive: true, force: true });
  console.error(error);
  app.exit(1);
});
