import { createRequire } from 'node:module';
import { mkdtemp, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { app, BrowserWindow, ipcMain } from 'electron';

const require = createRequire(import.meta.url);
const root = process.cwd();
const page = pathToFileURL(path.join(root, 'dist/index.html')).href;
const { registerConsentHandler } = require(path.join(root, 'dist-electron/main/consent.js'));
const { registerPasteHandler } = require(path.join(root, 'dist-electron/main/paste.js'));
const { registerReportHandler } = require(path.join(root, 'dist-electron/main/report-ipc.js'));
const { startSession, ingestSamples, stopSession } = require(path.join(root, 'dist-electron/main/session.js'));

const tmpData = await mkdtemp(path.join(os.tmpdir(), 'cp-s19-'));
const EPOCH = 1_700_000_000_000;

// 10 plies (none mate) so elevated gets >= 5 scored moves and settled gets < 5 (testing BOTH ok + insufficient in one real Stockfish pass!)
function pgnTenPlies(endEpochMs) {
  const end = new Date(endEpochMs);
  const pad = (v) => String(v).padStart(2, '0');
  const date = `${end.getUTCFullYear()}.${pad(end.getUTCMonth() + 1)}.${pad(end.getUTCDate())}`;
  const time = `${pad(end.getUTCHours())}:${pad(end.getUTCMinutes())}:${pad(end.getUTCSeconds())}`;
  return `[Event "Live Chess"]
[White "Ada"]
[Black "Nim"]
[Result "1-0"]
[TimeControl "60"]
[Termination "Ada won by resignation"]
[EndDate "${date}"]
[EndTime "${time}"]

1. e4 {[%clk 0:00:58]} e5 {[%clk 0:00:58]} 2. Nf3 {[%clk 0:00:56]} Nc6 {[%clk 0:00:56]} 3. Bb5 {[%clk 0:00:54]} a6 {[%clk 0:00:54]} 4. Ba4 {[%clk 0:00:52]} Nf6 {[%clk 0:00:52]} 5. O-O {[%clk 0:00:50]} Be7 {[%clk 0:00:50]} 1-0
`;
}

app.whenReady().then(async () => {
  registerConsentHandler(page);
  registerPasteHandler();
  registerReportHandler(() => tmpData);

  let mode = 'ok';
  ipcMain.handle('cp:session:start', async (_event, payload) => {
    const meta = await startSession(tmpData, { monoUs: 0, epochMs: EPOCH }, payload.timeControl);
    if (mode === 'ok') {
      const samples = [];
      // 0..60s baseline = 70 bpm (settled), 61..70s settled (72 bpm), 71..90s elevated (86 bpm).
      // Game is 20s long ending at 90s -> runs 70..90s: ~2 plies settled (<5 -> insufficient!), ~8 plies elevated (>=5 -> ok% + hatch!).
      for (let s = 0; s <= 90; s += 1) {
        samples.push({ tUs: s * 1_000_000, bpm: s <= 74 ? 70 : 86, confidence: 85, stable: true });
      }
      await ingestSamples(tmpData, samples);
    } else {
      await ingestSamples(tmpData, [
        { tUs: 0, bpm: 70, confidence: 85, stable: true },
        { tUs: 1_000_000, bpm: 71, confidence: 85, stable: true },
      ]);
    }
    return { sessionId: meta.id };
  });
  ipcMain.handle('cp:session:stop', async () => {
    const stopUs = mode === 'ok' ? 90_000_000 : 10_000_000;
    return stopSession(tmpData, { monoUs: stopUs, epochMs: EPOCH + stopUs / 1000 }, 'user');
  });

  const win = new BrowserWindow({
    width: 1120,
    height: 800,
    show: false,
    webPreferences: {
      preload: path.join(root, 'dist-electron/preload/index.js'),
      contextIsolation: true,
      sandbox: true,
      nodeIntegration: false,
    },
  });
  const consoleErrors = [];
  win.webContents.on('console-message', (_e, level, message) => {
    if (level >= 2) consoleErrors.push(message);
  });

  await win.loadURL(page);
  const pgn = pgnTenPlies(EPOCH + 90_000);

  const reportCheck = await win.webContents.executeJavaScript(`
    (async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      const clickText = (text) => {
        const btn = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === text);
        if (!btn) throw new Error('Missing button: ' + text);
        btn.click();
      };
      const setTextarea = (index, value) => {
        const el = document.querySelectorAll('textarea')[index];
        const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const waitSelector = async (sel) => {
        for (let i = 0; i < 120; i++) {
          const el = document.querySelector(sel);
          if (el) return el;
          await wait(50);
        }
        return null;
      };

      clickText('Allow the camera');
      await wait(100);
      clickText('Start sensing');
      await wait(100);
      clickText('Stop sensing');
      await wait(100);
      clickText('Paste PGNs');
      await wait(100);
      setTextarea(0, ${JSON.stringify(pgn)});
      await wait(150);
      clickText('Continue to report');

      const verdictEl = await waitSelector('h1.verdict-line');
      const verdictText = verdictEl?.textContent?.trim();
      const metaText = document.querySelector('.verdict-meta')?.textContent?.trim();

      // Verify hierarchy order: Verdict -> Timeline -> BandBars
      const sections = [...document.querySelectorAll('main > section')].map((el) => el.className);

      // Verify BandBars: settled insufficient (no fill, dashed track), elevated ok (% + hatch pattern)
      const settledInsufficient = document.querySelector('.band-settled .band-insufficient')?.textContent?.trim();
      const settledFillCount = document.querySelectorAll('.band-settled .band-fill-settled').length;
      const settledDashedTrack = document.querySelectorAll('.band-settled .band-track-insufficient').length;
      const elevatedValue = document.querySelector('.band-elevated .band-value')?.textContent?.trim();
      const elevatedCount = document.querySelector('.band-elevated .band-count')?.textContent?.trim();
      const elevatedFillHatch = document.querySelector('.band-elevated .band-fill-elevated')?.getAttribute('fill');

      // Stepper readout button check
      clickText('Next sample');
      await wait(50);
      const readoutAfterNext = document.querySelector('.timeline-readout')?.textContent?.trim();

      // Table toggle check
      clickText('Table');
      await wait(50);
      const tableCount = document.querySelectorAll('.data-table').length;
      const moveTableRowCount = document.querySelectorAll('.data-table')[0]?.querySelectorAll('tbody tr').length;
      const sampleTableRowCount = document.querySelectorAll('.data-table')[1]?.querySelectorAll('tbody tr').length;

      // Toggle back to Chart
      clickText('Chart');
      await wait(50);
      const chartBack = document.querySelectorAll('.timeline-frame svg').length;

      return {
        verdictText,
        metaText,
        sections,
        settledInsufficient,
        settledFillCount,
        settledDashedTrack,
        elevatedValue,
        elevatedCount,
        elevatedFillHatch,
        readoutAfterNext,
        tableCount,
        moveTableRowCount,
        sampleTableRowCount,
        chartBack,
      };
    })()
  `, true);

  mode = 'low';
  const refusalCheck = await win.webContents.executeJavaScript(`
    (async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      const clickText = (text) => {
        const btn = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === text);
        if (!btn) throw new Error('Missing button: ' + text);
        btn.click();
      };
      const setTextarea = (index, value) => {
        const el = document.querySelectorAll('textarea')[index];
        const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const waitSelector = async (sel) => {
        for (let i = 0; i < 80; i++) {
          const el = document.querySelector(sel);
          if (el) return el;
          await wait(50);
        }
        return null;
      };

      clickText('Back to session');
      await wait(100);
      clickText('Start sensing');
      await wait(100);
      clickText('Stop sensing');
      await wait(100);
      clickText('Paste PGNs');
      await wait(100);
      setTextarea(0, ${JSON.stringify(pgn)});
      await wait(150);
      clickText('Continue to report');
      await waitSelector('.refusal-panel');

      return {
        verdictCountOnRefusal: document.querySelectorAll('.verdict-section').length,
        bandBarsCountOnRefusal: document.querySelectorAll('.band-bars').length,
      };
    })()
  `, true);

  await rm(tmpData, { recursive: true, force: true });
  const ok =
    consoleErrors.length === 0 &&
    Boolean(reportCheck.verdictText) &&
    reportCheck.metaText?.includes('Baseline 70 bpm') &&
    reportCheck.sections[0] === 'verdict-section' &&
    reportCheck.sections[1]?.startsWith('timeline ') &&
    reportCheck.sections[2] === 'band-bars' &&
    reportCheck.settledInsufficient === 'Insufficient' &&
    reportCheck.settledFillCount === 0 &&
    reportCheck.settledDashedTrack === 1 &&
    /^\d+%$/.test(reportCheck.elevatedValue ?? '') &&
    reportCheck.elevatedFillHatch?.startsWith('url(#') &&
    reportCheck.readoutAfterNext?.startsWith('Sample 1/91') &&
    reportCheck.tableCount === 2 &&
    reportCheck.moveTableRowCount === 10 &&
    reportCheck.sampleTableRowCount === 91 &&
    reportCheck.chartBack === 1 &&
    refusalCheck.verdictCountOnRefusal === 0 &&
    refusalCheck.bandBarsCountOnRefusal === 0;

  console.log(JSON.stringify({ reportCheck, refusalCheck, consoleErrors, ok }, null, 2));
  app.exit(ok ? 0 : 1);
}).catch(async (error) => {
  await rm(tmpData, { recursive: true, force: true });
  console.error(error);
  app.exit(1);
});
