  font-size: 12px;
}

.game-players {
  color: var(--text);
  font-size: 15px;
  overflow-wrap: anywhere;
  flex: 1 1 200px;
}

.game-result {
  color: var(--text);
  font-family: ui-monospace, monospace;
  font-size: 13px;
}

.game-row-bottom {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
}

.game-ending {
  color: var(--text);
  font-size: 13px;
}

.game-detail {
  color: var(--muted);
  font-family: ui-monospace, monospace;
  font-size: 12px;
}

@media (max-width: 699px) {
  .verdict-line {
    font-size: 20px;
  }

  .band-grid {
    grid-template-columns: 1fr;
  }

  .report-layout .verdict-section {
    order: 1;
  }

  .report-layout .band-bars {
    order: 2;
    margin-top: 0;
    margin-bottom: 24px;
  }

  .report-layout .timeline {
    order: 3;
    margin-top: 0;
  }

  .report-layout .game-list-section {
    order: 4;
  }

  .timeline-wide {
    display: none;
  }

  .timeline-mini-stack {
    display: flex;
  }
}

