input.command:
cat << 'EOF' > /tmp/verify-s20-responsive.mjs
import { createRequire } from 'node:module';
import { mkdtemp, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { app, BrowserWindow, ipcMain } from 'electron';

const require = createRequire(import.meta.url);
const root = process.cwd();
const page = pathToFileURL(path.join(root, 'dist/index.html')).href;
const { registerConsentHandler } = require(path.join(root, 'dist-electron/main/consent.js'));
const { registerPasteHandler } = require(path.join(root, 'dist-electron/main/paste.js'));
const { registerReportHandler } = require(path.join(root, 'dist-electron/main/report-ipc.js'));
const { startSession, ingestSamples, stopSession } = require(path.join(root, 'dist-electron/main/session.js'));

const tmpData = await mkdtemp(path.join(os.tmpdir(), 'cp-s20-'));
const EPOCH = 1_700_000_000_000;
const LONG_NAME = 'GrandmasterLongUsernameFortyCharacters01';

const pgn1 = `[Event "Live Chess"]
[White "${LONG_NAME}"]
[Black "OpponentWithLongHandleAlsoWrappingWell02"]
[Result "1-0"]
[TimeControl "60"]
[Termination "${LONG_NAME} won by resignation"]

1. e4 {[%clk 0:00:58]} e5 {[%clk 0:00:58]} 2. Nf3 {[%clk 0:00:56]} Nc6 {[%clk 0:00:56]} 1-0
`;

const pgn2 = `[Event "Live Chess"]
[White "${LONG_NAME}"]
[Black "QuickAbort"]
[Result "*"]
[TimeControl "60"]
[Termination "Game aborted"]

*
`;

const pgn3 = `[Event "Live Chess"]
[White "Nim"]
[Black "${LONG_NAME}"]
[Result "0-1"]
[TimeControl "60"]
[Termination "${LONG_NAME} won on time"]

1. d4 {[%clk 0:00:58]} d5 {[%clk 0:00:58]} 2. c4 {[%clk 0:00:55]} e6 {[%clk 0:00:55]} 0-1
`;

app.whenReady().then(async () => {
  registerConsentHandler(page);
  registerPasteHandler();
  registerReportHandler(() => tmpData);

  ipcMain.handle('cp:session:start', async (_event, payload) => {
    const meta = await startSession(tmpData, { monoUs: 0, epochMs: EPOCH }, payload.timeControl);
    const samples = [];
    for (let s = 0; s <= 90; s += 1) {
      samples.push({ tUs: s * 1_000_000, bpm: s <= 60 ? 70 : 86, confidence: 85, stable: true });
    }
    await ingestSamples(tmpData, samples);
    return { sessionId: meta.id };
  });
  ipcMain.handle('cp:session:stop', async () => {
    return stopSession(tmpData, { monoUs: 90_000_000, epochMs: EPOCH + 90_000 }, 'user');
  });

  const win = new BrowserWindow({
    width: 1440,
    height: 900,
    show: false,
    webPreferences: {
      preload: path.join(root, 'dist-electron/preload/index.js'),
      contextIsolation: true,
      sandbox: true,
      nodeIntegration: false,
    },
  });
  const consoleErrors = [];
  win.webContents.on('console-message', (_e, level, message) => {
    if (level >= 2) consoleErrors.push(message);
  });

  await win.loadURL(page);

  await win.webContents.executeJavaScript(`
    (async () => {
      const wait = (ms) => new Promise((r) => setTimeout(r, ms));
      const clickText = (text) => {
        const btn = [...document.querySelectorAll('button')].find((b) => b.textContent?.trim() === text);
        if (!btn) throw new Error('Missing button: ' + text);
        btn.click();
      };
      const setTextarea = (index, value) => {
        const el = document.querySelectorAll('textarea')[index];
        const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
      };
      const waitSelector = async (sel) => {
        for (let i = 0; i < 120; i++) {
          const el = document.querySelector(sel);
          if (el) return el;
          await wait(50);
        }
        return null;
      };

      clickText('Allow the camera');
      await wait(100);
      clickText('Start sensing');
      await wait(100);
      clickText('Stop sensing');
      await wait(100);
      clickText('Paste PGNs');
      await wait(100);

      setTextarea(0, ${JSON.stringify(pgn1)});
      setTextarea(1, ${JSON.stringify(pgn2)});
      setTextarea(2, ${JSON.stringify(pgn3)});
      await wait(150);
      clickText('Continue to report');
      await waitSelector('.game-list-section');
    })()
  `, true);

  const measure = () =>
    win.webContents.executeJavaScript(`
      (() => {
        const wideEl = document.querySelector('.timeline-wide');
        const miniEl = document.querySelector('.timeline-mini-stack');
        const verdictRect = document.querySelector('.verdict-section')?.getBoundingClientRect();
        const bandRect = document.querySelector('.band-bars')?.getBoundingClientRect();
        const timelineRect = document.querySelector('.timeline')?.getBoundingClientRect();
        const gameRows = [...document.querySelectorAll('.game-row')];
        const longText = gameRows[0]?.querySelector('.game-players')?.textContent ?? '';
        const excludedBadges = document.querySelectorAll('.game-list .meta-excluded').length;
        const summaryNote = document.querySelector('.game-list-header .band-note')?.textContent?.trim();
        const miniCards = document.querySelectorAll('.mini-card').length;
        return {
          innerWidth: window.innerWidth,
          scrollWidth: document.documentElement.scrollWidth,
          wideDisplay: wideEl ? getComputedStyle(wideEl).display : null,
          miniDisplay: miniEl ? getComputedStyle(miniEl).display : null,
          verdictTop: Math.round(verdictRect?.top ?? -1),
          bandTop: Math.round(bandRect?.top ?? -1),
          timelineTop: Math.round(timelineRect?.top ?? -1),
          gameRowCount: gameRows.length,
          hasFullLongName: longText.includes(${JSON.stringify(LONG_NAME)}),
          excludedBadges,
          summaryNote,
          miniCards,
        };
      })()
    `, true);

  const wide = await measure();
  win.setContentSize(640, 900);
  await new Promise((r) => setTimeout(r, 150));
  const narrow = await measure();

  await rm(tmpData, { recursive: true, force: true });
  const ok =
    consoleErrors.length === 0 &&
    wide.scrollWidth <= wide.innerWidth &&
    wide.wideDisplay === 'block' &&
    wide.miniDisplay === 'none' &&
    wide.verdictTop < wide.timelineTop &&
    wide.timelineTop < wide.bandTop &&
    wide.gameRowCount === 3 &&
    wide.hasFullLongName &&
    wide.excludedBadges >= 1 &&
    wide.summaryNote === '3 games · 2 in accuracy · 1 aborted' &&
    narrow.innerWidth === 640 &&
    narrow.scrollWidth <= narrow.innerWidth &&
    narrow.wideDisplay === 'none' &&
    narrow.miniDisplay === 'flex' &&
    narrow.miniCards === 3 &&
    narrow.verdictTop < narrow.bandTop &&
    narrow.bandTop < narrow.timelineTop;

  console.log(JSON.stringify({ wide, narrow, consoleErrors, ok }, null, 2));
  app.exit(ok ? 0 : 1);
}).catch(async (error) => {
  await rm(tmpData, { recursive: true, force: true });
  console.error(error);
  app.exit(1);
});
EOF
npx electron --no-sandbox /tmp/verify-s20-responsive.mjs
STATUS=$?
rm -f /tmp/verify-s20-responsive.mjs
exit $STATUS
